using UnityEditor;
using Homesteader.UI;
using UnityEngine;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        if (hud == null) { result.Log("no HudRoot"); return; }
        var b = hud.GetComponent<HudSceneBootstrap>();
        if (b == null) { result.Log("no bootstrap"); return; }
        var so = new UnityEditor.SerializedObject(b);
        var prop = so.FindProperty("_enableKitOverlay");
        if (prop != null)
        {
            bool was = prop.boolValue;
            prop.boolValue = false;
            so.ApplyModifiedProperties();
 result.Log("kit overlay: was=" + was);
        }
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        result.Log("scene saved.");
    }
}
